import { db } from '../db/client.js';

export async function login(email, password) {
  const user = await db.get('SELECT id, email, password_hash FROM users WHERE email = ?', [email]);
  if (!user) {
    return null;
  }
  return verify(user.password_hash, password) ? { id: user.id, email: user.email } : null;
}

// Minimal sqlite-shaped client so the sources are readable without a real DB.
export const db = {
  async all(sql, params = []) { return []; },
  async get(sql, params = []) { return null; },
  async run(sql, params = []) { return { changes: 1 }; },
};

CREATE TABLE users (
  id            INTEGER PRIMARY KEY,
  email         TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  created_at    TEXT NOT NULL
);

CREATE TABLE products (
  id       INTEGER PRIMARY KEY,
  name     TEXT NOT NULL,
  price    INTEGER NOT NULL,
  stock    INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE orders (
  id          INTEGER PRIMARY KEY,
  user_id     INTEGER NOT NULL REFERENCES users(id),
  order_no    TEXT NOT NULL,
  total       INTEGER NOT NULL,
  status      TEXT NOT NULL,
  created_at  TEXT NOT NULL
);

